using Astrea.BattleActions;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurificationCorruptionOverflowEffect", menuName = "Data/Battle/Effects/Sentinels/PurificationCorruptionOverflow Effect")]
public class PurificationCorruptionOverflowEffect : Effect
{
	[Header("OverpurifyOvercorrupt")]
	[SerializeField]
	[AllowNesting]
	private OmenLogicActionFace omenLogicActionFace;

	[Space(100f)]
	[SerializeField]
	private int amountToTrigger;

	[Header("Overcorrupt")]
	[SerializeField]
	private bool overcorrupt;

	[Header("GainEmpower")]
	[SerializeField]
	private bool gainEmpower;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		if (gainEmpower)
		{
			return Smart.Format(base.localizationManager.GetLocalizedString("EveryXTimesPlayVirtue"), amountToTrigger) + base.localizationManager.GetLocalizedSpace() + omenLogicActionFace.ActionFace.BattleAction.GetActionDescription(omenLogicActionFace.ActionFace.ActionValue).LowercaseFirst();
		}
		return Smart.Format(GetLocalizedDescription(), amountToTrigger, omenLogicActionFace.ActionFace.BattleAction.GetActionDescription(omenLogicActionFace.ActionFace.ActionValue).LowercaseFirst());
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (overcorrupt)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
			{
				if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
				{
					EffectIncreasedDefault(effectAmount, effectOwner, source);
				}
			});
		}
		else
		{
			EffectIncreasedDefault(effectAmount, effectOwner, source);
		}
	}

	private void EffectIncreasedDefault(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (effectAmount >= amountToTrigger)
		{
			CompanionEffects component = effectOwner.GetComponent<CompanionEffects>();
			component.IsEffectActive(this);
			component.IsEffectActiveAndDecreaseEffect(this, effectAmount, activateFeedback: false, removeOnZero: false);
			if (omenLogicActionFace.ActionFace.BattleAction is PurifiedLightningAction)
			{
				(omenLogicActionFace.ActionFace.BattleAction as PurifiedLightningAction).AreaCastTargetAmount(omenLogicActionFace.OmenLogic.GetTargets(), omenLogicActionFace.ActionFace.ActionValue, null);
			}
			else
			{
				omenLogicActionFace.OmenLogic.ActivateOmen(omenLogicActionFace.ActionFace.BattleAction, omenLogicActionFace.ActionFace.ActionValue, effectOwner, null);
			}
			PlaySecondEffectActivationSFX();
			SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
		else
		{
			PlayEffectActivationSFX();
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
	}
}
